<div class="solution-stage-grid" role="group" aria-label="Explore the eight proposed workflow stages">${SOLUTION_STAGES.map((s,i)=>`<button type="button" class="solution-stage ${i===0?'active':''}" data-action="solution-step" data-step="${i}" aria-pressed="${i===0?'true':'false'}"><span class="stage-top"><span class="stage-number">${String(i+1).padStart(2,'0')}</span><span class="stage-icon" aria-hidden="true">${s.icon}</span></span><span class="stage-name">${s.title}</span><span class="stage-desc">${s.teaser}</span><span class="stage-foot"><span>${s.label}</span><span aria-hidden="true">↗</span></span></button>`).join('')}</div>
